import React, {ElementRef,useRef} from 'react';
import {Button} from "../../../components/Button";
import {Container} from "../../../components/Container";
import emailjs from '@emailjs/browser';
import {SectionTitle} from "../../../components/SectionTitle";
import styled from "styled-components";
import {theme} from "../../../styles/Theme";


export const Contact = () => {
    const form = useRef<ElementRef<'form'>>(null);

    const sendEmail = (e: any) => {
        e.preventDefault();

        if (!form.current) return

        emailjs
            .sendForm('service_ztueer8', 'template_ctub61e', form.current, {
                publicKey: 'mK6eR3VyXfjdF7_yb',
            })
            .then(
                () => {
                    console.log('SUCCESS!');
                },
                (error) => {
                    console.log('FAILED...', error.text);
                },
            );
        e.target.reset()
    };
    return (
        <StyledContacts id={"contact"}>
            <Container>
                <SectionTitle>Contacts</SectionTitle>

                <Form ref={form} onSubmit={sendEmail}>
                    <span>Name</span>
                    <Field required placeholder={"name"} name={'user_name'}/>
                    <span>Email</span>
                    <Field required placeholder={"email"} name={'email'}/>
                    <span>Subject</span>
                    <Field required placeholder={"subject"} name={'subject'}/>
                    <span>Message</span>
                    <Field required placeholder={"message"} as={"textarea"} name={'message'}/>
                    <Button type={"submit"}>Submit</Button>
                </Form>

            </Container>
        </StyledContacts>
    )
    }

    const StyledContacts = styled.section`
        & span {
            align-self: start;
            margin-bottom: 6px;
            font-family: "Montserrat", sans-serif;
            font-weight: 400;
            font-size: 14px;
            color: #1f2626;
        }
        
        ${Button} {
            padding: 12px 20px;
            width: 532px;
            height: 48px;
            
            @media ${theme.media.mobile} {
                width: 350px;
            }
            
        }
    `

    const Form = styled.form`
        max-width: 532px;
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        margin: 0 auto;

        textarea {
            resize: none;
            height: 165px;
        }

       
    `

    const Field = styled.input`
        font-family: "Montserrat", sans-serif;
        border-radius: 6px;
    background-color: white;
        
    border: 1px solid #5222d0;
    width: 100%;
    padding: 15px 18px;
    font-weight: 400;
    font-size: 14px;
    letter-spacing: 0.05em;
    color:  #1f2626;
        margin-bottom: 25px;
    
    &::placeholder {
        color:#919b9b;
        text-transform: capitalize;
    }
    
    &:focus-visible {
        outline: 1px solid white;
    }
        
        &:focus-visible {
            border: 2px solid #5222d0;
        }
    `