import React, {useState} from 'react';
import {Button} from "../../../components/Button";
import {FlexWrapper} from "../../../components/FlexWrapper";
import { S } from './Projects_Styles';


export type ProjectPropsType = {
    title: string;
    text: string;
    src: string;
    skills: string[];
    id: number;
};

type WorkProps = {
    projects: ProjectPropsType[];
};

export const Project: React.FC<WorkProps> = ({ projects }) => {
    const [showAll, setShowAll] = useState(false);
    const displayedProjects = showAll ? projects : projects.slice(0, 2);
    return (
<>
    <FlexWrapper wrap={"wrap"} columnGap={"27px"} rowGap={"43px"}>
    {displayedProjects.map((project) => (
        <S.Project key={project.id}>
            <FlexWrapper direction={"column"} wrap={"wrap"}>
                <S.PhotoWrapper>
                    <S.Photo src={project.src} alt={project.title} />
                    <Button>view project</Button>
                </S.PhotoWrapper>
                <S.Description>
                    <S.Title>{project.title}</S.Title>
                    <S.ListSkills>
                        {project.skills.map((skill, index) => (
                            <S.SkillItem key={index}>{skill}</S.SkillItem>
                        ))}
                    </S.ListSkills>
                    <S.Text>{project.text}</S.Text>
                </S.Description>
            </FlexWrapper>
        </S.Project>
    ))}
    </FlexWrapper>
        <S.BtnWrapper>
            <Button  onClick={() => setShowAll(!showAll)}>
                {showAll ? 'Show Less' : 'See All projects'}
            </Button>
        </S.BtnWrapper>
</>
    );
};

