import styled from "styled-components";
import {theme} from "../../../styles/Theme";

const AboutMe = styled.section`
    padding-top: 300px;
    
    h2 {
        margin: 0 0 20px 17px;
    }
    
    @media screen and (max-width: 1046px){
        padding-top: 200px;
    }
    
    @media ${theme.media.mobile} {
        padding-top: 72px;
    }
`

const Text = styled.p`
    margin-left: 17px;
    max-width: 865px;
    font-size: 18px;
    line-height: 144%;
    position: relative;

    &::before {
        content: "";
        display: inline-block;
        border-radius: 2px;
        width: 116px;
        height: 5px;
        background-color: ${theme.colors.accent};
        transform: rotate(90deg);
        top: 62px;
        left: -75px;

        position: absolute;
    }

 
`

export const S = {
    AboutMe,
    Text
}