import styled from "styled-components";
import {Button} from "../../../components/Button";
import {theme} from "../../../styles/Theme";
import {FlexWrapper} from "../../../components/FlexWrapper";

const Projects = styled.section`
    
    ${FlexWrapper} {
        @media ${theme.media.mobile} {
            gap: 20px;
        }
    }
`

const Project=styled.div`
    box-shadow: 2px 2px 32px 0 rgba(40, 38, 44, 0.15);
    background: #f5f2fd;
    border-radius: 6px;
    width: 363px;
    padding-bottom: 30px;
    display: flex;
    flex-grow: 1;
`

const PhotoWrapper = styled.div`
    position: relative;

    ${Button} {
        opacity: 0;
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -40%);
        transition: ${theme.animations.transition};
        
        &::before {
            width: 100%;
            height: 100%;
        }

    }

    &::before {
        content: "";
        position: absolute;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;

        backdrop-filter: blur(4px);
        background: rgba(255, 255, 255, 0.44);

        opacity: 0;
        transition: ${theme.animations.transition};
    }

    &:hover {

        &::before {
            opacity: 1;
        }

        ${Button} {
            opacity: 1;
            transform: translate(-50%, -50%);
        }
    }

    @media ${theme.media.tablet} {
        &::before {
            opacity: 1;
        }

        ${Button} {
            opacity: 1;
        }
    }
`

const Photo = styled.img`
    width: 100%;
    max-height: 388px;
    object-fit: cover;
`

const Description = styled.div`
    display: flex;
    flex-direction: column;
    padding: 0 9px 0 26px;

    @media ${theme.media.mobile} {
        padding: 0 8px 0 18px;
    }
`

const Title = styled.h3`
    margin-top: 30px
`

const ListSkills = styled.ul`
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin: 10px 0 20px;

    @media ${theme.media.mobile} {
        margin-bottom: 16px;
    }
`

const SkillItem = styled.li`
    border-radius: 4px;
    padding: 8px 16px;
    color: ${theme.colors.fontBtnText};
    height: 30px;
    background-color: ${theme.colors.accent};
    text-align: center;
    font-weight: 400;
    font-size: 10px;
    line-height: 140%;
    letter-spacing: 0.12em;
    text-transform: uppercase;
`

const Text = styled.p``

const BtnWrapper = styled.div`
    display: flex;
    justify-content: center;

    
    ${Button} {
        width: 305px;
        margin-top: 36px;
        text-transform: uppercase;
        font-weight: 500;
        font-size: 16px;
        text-align: center;
        color: #dbffff;
    }
`


export const S = {
    Projects,
    Project,
    PhotoWrapper,
    Photo,
    Description,
    Title,
    ListSkills,
    SkillItem,
    Text,
    BtnWrapper
}